
 create schema private;create role anon;create role authenticated;grant usage on schema private to authenticated;
 create function private.dashboard_admin_live_scope() returns jsonb language plpgsql stable as $$begin if coalesce(current_setting('test.scope',true),'')='' then raise exception 'unauthorized';end if;return current_setting('test.scope')::jsonb;end$$;
 create function private.dashboard_scope_allows(jsonb,text,text) returns boolean language sql immutable as $$select $1->>'mode'='all' or coalesce($1->'countries' ? $2,false)$$;
 create function private.dashboard_admin_live_report_country(text,text) returns text language sql immutable as $$select case when $1 in('BR_PANGHU','胖虎巴西') then '胖虎巴西' when $1='IN' then '印度' else $1 end$$;
 create table fixture_feeds(value jsonb);
 create table fixture_platforms(id uuid,name text,team text,country text,scope_group text,source text,timezone text,currency text,source_name text);
 create function private.dashboard_admin_live_platforms() returns table(id uuid,name text,team text,country text,scope_group text,source text,timezone text,currency text,source_name text) language sql stable as $$select * from public.fixture_platforms p where private.dashboard_scope_allows(private.dashboard_admin_live_scope(),p.country,p.name)$$;
 create table ar_collected_orders(country_code text,platform text,order_kind text,source_system text,applied_at timestamp,completed_at timestamp,updated_at timestamptz);
 create index ar_created on ar_collected_orders(country_code,platform,order_kind,applied_at);create index ar_completed on ar_collected_orders(country_code,platform,order_kind,completed_at);
 create table newar_detail_platforms(platform text,country_code text,enabled boolean,launch_at timestamptz);
 create table newar_detail_records(platform text,dataset text,created_at timestamptz,success_at timestamptz,status_group text,received_at timestamptz);
 create table game66_charge_orders(platform_id uuid,create_time timestamptz,last_seen_at timestamptz);
 create table game66_withdraw_orders(like game66_charge_orders);
 create table game66_sync_runs(platform_id uuid,data_type text,window_start timestamptz,window_end timestamptz,status text,finished_at timestamptz,rows_fetched int,started_at timestamptz,error_message text);
 create table third_party_volume(country text,platform text,data_date date,direction text,sheet_name text,quarantined_at timestamptz,updated_at timestamptz,amount numeric);
 create table panda_success_rate_daily(country text,country_code text,platform text,stat_date date,direction text,updated_at timestamptz);
 create table lg_success_daily(country_code text,platform text,stat_date date,order_kind text,observed_at timestamptz,updated_at timestamptz);
 create table lg_orders(country_code text,platform text,order_kind text,created_at timestamptz,updated_at timestamptz);
 create table lg_sync_runs(country_code text,platform text,stat_date date,order_kind text,status text,sync_mode text,expected_count bigint,fetched_count bigint,published_at timestamptz,observed_at timestamptz);
 create table collection_success_daily(country_code text,platform text,stat_date date,source_system text,snapshot_at timestamptz,updated_at timestamptz);
 create table newar_business_snapshots(country text,country_code text,platform text,stat_date date,kind text,direction text,captured_at timestamptz,updated_at timestamptz);
 create table auto_withdraw_daily(country text,platform text,data_date date,source_updated_at timestamptz,updated_at timestamptz);
 create table ar_config_targets(country_code text,country_name text,platform text,timezone text,source_system text);create table panda_config_targets(like ar_config_targets);create table wg_config_targets(like ar_config_targets);
 create table ar_config_daily(country_code text,platform text,observed_local_date date,received_at timestamptz);create table panda_config_daily(like ar_config_daily);create table wg_config_daily(like ar_config_daily);
