alter table third_party_volume add column raw_channel text,add column channel text,add column count bigint,add column source_row int;
alter table auto_withdraw_daily add column source_sheet text;
alter table ar_config_daily add column parser_version text;
alter table lg_orders add column order_no text,add column order_amount numeric,add column status_text text,add column status_class text,add column paid_at timestamptz,add column finished_at timestamptz,add column third_party text,add column raw_channel text;
create table game66_platforms(id uuid,team_code text,team_name text,platform_name text);
create table game66_review_rules(platform_id uuid,last_seen_at timestamptz);
create table dashboard_platform_team_map(team_name text,platform_name text,source_system text,source_country text,source_platform text,active boolean);
create table private.dashboard_admin_collected_feed_rows(dataset text,country text,platform text,data_date date,direction text,provider text,metrics jsonb,updated_at timestamptz);
create function private.dashboard_admin_live_deposit_platform_key(c text,p text)returns text language sql immutable as $$select lower(btrim(p))$$;
create function private.dashboard_admin_live_withdraw_key(p text)returns text language sql immutable as $$select lower(btrim(p))$$;
create function private.dashboard_admin_live_lg_scopes()returns table(country_code text,platform text)language sql as $$select distinct country_code,platform from public.lg_orders$$;
create function private.dashboard_admin_live_order_intake()returns jsonb language plpgsql stable as $$begin if current_setting('test.intake_error',true)='true' then raise exception 'intake_expensive_branch_called';end if;return '[{"dataset":"orders","name":"INTAKE","records":999}]'::jsonb;end$$;
create function private.team_sheet_catalog(s jsonb)returns jsonb language plpgsql stable as $$begin if current_setting('test.team_error',true)='true' then raise exception 'team_catalog_called';end if;return '[{"dataset":"team_sheet","name":"TEAM","country":"印度","directions":["charge"],"firstDate":"2026-09-19"}]'::jsonb;end$$;
create function private.dashboard_admin_wg_sites()returns table(site_code text,country_code text,country text,platform text)language sql stable as $$select 'fixture'::text,'PH'::text,'菲律宾'::text,'WG'::text where false$$;
create function private.dashboard_admin_live_wg_day_evidence(text,text,date)returns jsonb language sql stable as $$select '{}'::jsonb$$;
create role service_role;
